static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }
    // Strip query part
    int q = name.indexOf('?');
    if (q >= 0) {
        name = name.substring(0, q);
    }
    // Remove any leading file separators to avoid absolute paths
    while (!name.isEmpty() && (name.charAt(0) == '/' || name.charAt(0) == '\\')) {
        name = name.substring(1);
    }

    Path dirPath = dir.toPath().toAbsolutePath().normalize();
    Path targetPath = dirPath.resolve(name).normalize();

    if (!targetPath.startsWith(dirPath)) {
        throw new IllegalArgumentException("Invalid file name: path traversal detected");
    }

    File file = targetPath.toFile();

    // Determine prefix/suffix based on original name (without path components)
    String simpleName = targetPath.getFileName().toString();
    int dot = simpleName.lastIndexOf('.');
    String prefix = dot < 0 ? simpleName : simpleName.substring(0, dot);
    String suffix = dot < 0 ? "" : simpleName.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        targetPath = dirPath.resolve(newName).normalize();
        file = targetPath.toFile();
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}
