import java.io.InputStream;
import java.security.SecureRandom;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;

/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>The original implementation seeded the {@code SecureRandom} with data
 * supplied via a {@link Resource}.  Because that data can be attacker‑controlled
 * (or otherwise predictable), using it as a seed weakens the randomness and
 * may lead to predictable cryptographic material.  The patched version
 * therefore never uses external seed data.  It relies on the JVM’s built‑in
 * seeding mechanism, which gathers entropy from the operating system.
 *
 * <p>If a {@code seed} resource is configured, the resource is read and closed
 * (to avoid resource leaks) but its contents are deliberately ignored.  A
 * warning is logged so that developers are aware that the configuration is
 * ineffective and should be removed.
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private static final Logger logger = Logger.getLogger(SecureRandomFactoryBean.class.getName());

    /** Algorithm name (e.g., "SHA1PRNG").  If {@code null} or empty the default
     *  SecureRandom implementation is used. */
    private String algorithm = "SHA1PRNG";

    /** Optional external seed resource – retained for backward compatibility
     *  but ignored for security reasons. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        // -------------------------------------------------------------------
        // 1. Create the SecureRandom instance using the configured algorithm.
        //    If the algorithm is not set or invalid, fall back to the default
        //    constructor which uses the strongest provider available.
        // -------------------------------------------------------------------
        SecureRandom rnd;
        if (algorithm != null && !algorithm.trim().isEmpty()) {
            try {
                rnd = SecureRandom.getInstance(algorithm);
            } catch (Exception e) {
                // If the requested algorithm is unavailable, log and fallback.
                logger.log(Level.WARNING,
                        "Requested SecureRandom algorithm \"{0}\" is not available; using default implementation.",
                        algorithm);
                rnd = new SecureRandom();
            }
        } else {
            rnd = new SecureRandom();
        }

        // -------------------------------------------------------------------
        // 2. Force the SecureRandom instance to self‑seed using OS entropy.
        //    This call guarantees that the internal state is initialized even
        //    on JVMs that lazily seed on first use.
        // -------------------------------------------------------------------
        rnd.nextBytes(new byte[1]);

        // -------------------------------------------------------------------
        // 3. Handle the (now ignored) external seed resource.
        //    The resource is read and closed to avoid leaking file handles,
        //    but its data is NOT passed to setSeed().
        // -------------------------------------------------------------------
        if (seed != null) {
            try (InputStream is = seed.getInputStream()) {
                // Read and discard – the act of reading ensures the stream is
                // consumed and closed, but the bytes are not used for seeding.
                byte[] buffer = new byte[1024];
                while (is.read(buffer) != -1) {
                    // no‑op
                }
                logger.log(Level.WARNING,
                        "SecureRandomFactoryBean: external seed resource is configured but ignored for security reasons.");
            } catch (IOException ioe) {
                // Log the problem but do not fail the bean creation – the
                // SecureRandom instance is still usable.
                logger.log(Level.WARNING,
                        "Failed to read external seed resource; proceeding with default SecureRandom seeding.", ioe);
            }
        }

        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // Each call returns a freshly‑initialized SecureRandom instance.
        return false;
    }

    // -----------------------------------------------------------------------
    // Setters for dependency injection (e.g., via Spring)
    // -----------------------------------------------------------------------

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }
