/**
 * Extends the sign of the given value {@code v} that was read using {@code t}
 * bits. This method follows the JPEG specification for the "extend" operation.
 *
 * <p>The original implementation used a {@code while} loop that recomputed the
 * threshold {@code vt} on each iteration, which could lead to an infinite loop
 * for crafted inputs (e.g., when {@code t} was zero or negative). The loop has
 * been replaced with a single, well‑defined conditional and strict input
 * validation to guarantee termination and prevent denial‑of‑service attacks.</p>
 *
 * @param v the raw value read from the bitstream (must be in the range
 *          {@code 0 <= v < 2^t})
 * @param t the number of bits used to represent {@code v} (must be between
 *          1 and 31 inclusive)
 * @return the sign‑extended integer value
 * @throws IllegalArgumentException if {@code t} or {@code v} are out of the
 *         expected ranges
 */
private int extend(int v, int t) {
    // Validate bit length: JPEG uses at most 16 bits for this operation,
    // but we guard against any unreasonable value that could cause overflow.
    if (t <= 0 || t > 31) {
        throw new IllegalArgumentException("Bit length 't' must be between 1 and 31, got: " + t);
    }

    // The raw value must fit into the specified number of bits.
    int maxValue = 1 << t;               // 2^t
    if (v < 0 || v >= maxValue) {
        throw new IllegalArgumentException(
                "Value 'v' out of range for the given bit length: v=" + v + ", t=" + t);
    }

    // Threshold for sign detection.
    int vt = 1 << (t - 1);               // 2^(t-1)

    // If the most‑significant bit is 0, the value is negative and must be
    // sign‑extended. The original loop performed this repeatedly; a single
    // adjustment is sufficient.
    if (v < vt) {
        v += (-1 << t) + 1;              // Equivalent to v - (1 << t) + 1
    }

    return v;
