private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path basePath = targetDirectory.getCanonicalFile().toPath();

    ArchiveEntry entry;
    while ((entry = supplier.getNextReadableEntry()) != null) {
        String entryName = entry.getName();

        // reject null or empty names
        if (entryName == null || entryName.isEmpty()) {
            continue; // or throw
        }

        // Normalize the entry name to prevent traversal
        Path entryPath = Paths.get(entryName).normalize();

        // Disallow absolute paths or paths that escape the base directory
        if (entryPath.isAbsolute() || entryPath.startsWith("..") || entryPath.toString().contains(".."+File.separator)) {
            throw new IOException("Invalid entry name: " + entryName);
        }

        File targetFile = new File(targetDirectory, entryPath.toString());

        // Resolve canonical path and ensure it stays inside targetDirectory
        Path canonicalTarget = targetFile.getCanonicalFile().toPath();
        if (!canonicalTarget.startsWith(basePath)) {
            throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
        }

        if (entry.isDirectory()) {
            // create directory, then re‑validate
            Files.createDirectories(canonicalTarget);
            // re‑check after creation
            if (!canonicalTarget.startsWith(basePath)) {
                throw new IOException("Directory traversal after creation: " + entryName);
            }
        } else {
            // ensure parent directory exists
            Path parent = canonicalTarget.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
                if (!parent.startsWith(basePath)) {
                    throw new IOException("Parent directory traversal for entry: " + entryName);
                }
            }

            // write file data
            try (OutputStream out = Files.newOutputStream(canonicalTarget, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(entry, out);
            }
        }
    }
}

