private void expand(ArchiveEntrySupplier supplier,
                    EntryWriter writer,
                    File targetDirectory) throws IOException {

    // Canonical base directory – the only location we allow files to be created under.
    final Path basePath = targetDirectory.getCanonicalFile().toPath();

    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String rawName = entry.getName();

        // Defensive: skip null/empty names (they cannot be written safely).
        if (rawName == null || rawName.isEmpty()) {
            entry = supplier.getNextReadableEntry();
            continue;
        }

        /* -------------------------------------------------------------
         *  1. Normalise the entry name and reject dangerous patterns.
         * ------------------------------------------------------------- */
        Path entryPath = Paths.get(rawName).normalize();

        // Disallow absolute paths (e.g. "/etc/passwd") and any path that
        // resolves to a location outside the target directory.
        if (entryPath.isAbsolute()
                || entryPath.startsWith("..")
                || entryPath.toString().contains(".." + File.separator)) {
            throw new IOException("Invalid archive entry name: " + rawName);
        }

        /* -------------------------------------------------------------
         *  2. Resolve the final file location inside the target directory.
         * ------------------------------------------------------------- */
        File targetFile = new File(targetDirectory, entryPath.toString());
        Path canonicalTarget = targetFile.getCanonicalFile().toPath();

        // Final safety check – the canonical path must stay within the base.
        if (!canonicalTarget.startsWith(basePath)) {
            throw new IOException("Expanding " + rawName
                    + " would create a file outside of " + targetDirectory);
        }

        /* -------------------------------------------------------------
         *  3. Create directories or write file data.
         * ------------------------------------------------------------- */
        if (entry.isDirectory()) {
            // Create the directory (including any missing parents) and re‑validate.
            Files.createDirectories(canonicalTarget);
            if (!canonicalTarget.startsWith(basePath)) {
                throw new IOException("Directory traversal after creation for entry: " + rawName);
            }
        } else {
            // Ensure the parent directory exists and is inside the base directory.
            Path parent = canonicalTarget.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
                if (!parent.startsWith(basePath)) {
                    throw new IOException("Parent directory traversal for entry: " + rawName);
                }
            }

            // Write the entry's data to the target file.
            try (OutputStream out = Files.newOutputStream(canonicalTarget,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(entry, out);
            }
        }

        // Proceed to the next entry.
        entry = supplier.getNextReadableEntry();
    }
}
