private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – they are cached in a
    // ByteArrayInputStream so that we know the exact size.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize(); // may be -1 for malformed archives
    // If the size is known and we have already read it, signal EOF.
    if (csize >= 0 && current.bytesRead >= csize) {
        return -1;
    }

    // Fill the internal buffer if it is empty.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        // Defensive: InputStream.read may return 0, which would otherwise cause an
        // infinite loop. Treat 0 as EOF for a stored entry.
        if (l <= 0) {
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // If the declared size is known, make sure we never read past it.
        if (csize >= 0 && current.bytesReadFromStream > csize) {
            // The stream supplied more data than the entry claims – this is a
            // corrupted ZIP. Throw an exception rather than silently truncating
            // or looping forever.
            throw new IOException("Stored entry size mismatch: read "
                    + current.bytesReadFromStream + " bytes but header declares "
                    + csize + " bytes");
        }
    }

    // Determine how many bytes we can safely return.
    int toRead = Math.min(buf.remaining(), length);
    if (csize >= 0) {
        long remaining = csize - current.bytesRead;
        if (remaining <= 0) {
            return -1;
        }
        if (remaining < toRead) {
            toRead = (int) remaining;
        }
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
