        }
    }
    return 0;
}

private static int[] parseVersion(String version) {
    String[] parts = version.trim().split("\\.");
    int[] nums = new int[3];
    for (int i = 0; i < 3; i++) {
        if (i < parts.length) {
            String part = parts[i].trim();
            if (part.isEmpty()) {
                nums[i] = 0;
                continue;
            }
            try {
                nums[i] = Integer.parseInt(part);
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid version component: '" + part + "' in version '" + version + "'", e);
            }
            if (nums[i] < 0) {
                throw new IllegalArgumentException("Version components must be non‑negative: '" + part + "'");
            }
        } else {
            nums[i] = 0;
        }
    }
    return nums;
}
