import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods ...

    /**
     * Determines whether the current request is allowed to perform a self‑update.
     * <p>
     * The method now enforces that the authenticated user (derived from the
     * {@link HttpServletRequest#getUserPrincipal()} or a {@code user_id} request
     * attribute) matches the user identifier extracted from the request URL.
     * This prevents a malicious caller from updating another user's record.
     * </p>
     *
     * @param request the incoming HTTP request
     * @return {@code true} if the update is permitted, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {
        // 1️⃣ Verify that the caller is authenticated and is the owner of the
        //    resource identified by the path variable.
        String pathUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        String authenticatedUserId = extractAuthenticatedUserId(request);
        if (authenticatedUserId == null || !Objects.equals(authenticatedUserId, pathUserId)) {
            // Not the same user – deny the operation.
            return false;
        }

        // 2️⃣ Read and deserialize the request payload.
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            return false;
        }

        // 3️⃣ Load the persisted user record.
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(pathUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot safely allow the update.
            return false;
        }

        // 4️⃣ Ensure that immutable fields have not been tampered with.
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the self‑update is allowed.
        return true;
    }

    /**
     * Extracts the identifier of the authenticated user from the request.
     * <p>
     * The method first checks {@link HttpServletRequest#getUserPrincipal()}.
     * Some environments (e.g., Spring Security) may store the user identifier
     * as a request attribute named {@code user_id}; this is used as a fallback.
     * </p>
     *
     * @param request the incoming HTTP request
     * @return the authenticated user identifier, or {@code null} if the request
     *         is unauthenticated
     */
    private String extractAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        if (principal != null) {
            return principal.getName();
        }
        Object attr = request.getAttribute("user_id");
        return (attr instanceof String) ? (String) attr : null;
    }

